ControlPropertyState.AutoRuleBindingString:
Refresh('CH-Tbl-SystemHeartbeat');
Refresh('CH-Tbl-Received Emails');
UpdateContext(
    {
        varLatido: LookUp('CH-Tbl-SystemHeartbeat', Name = "ingesta-correos"),
        varEsperandoBanca: CountRows(
            Filter('CH-Tbl-Received Emails',
                EmailReviewStatus = 'EmailReviewStatus (CH-Tbl-Received Emails)'.'Revision manual')),
        varSospechosos: CountRows(
            Filter('CH-Tbl-Received Emails',
                SenderClassification = 'SenderClassification (CH-Tbl-Received Emails)'.Sospechoso)),
        varPendientes: CountRows(
            Filter('CH-Tbl-Received Emails',
                ValidationStatus = 'ValidationStatus (CH-Tbl-Received Emails)'.Pendiente)),
        varErroresSistema: CountRows(
            Filter('CH-Tbl-Received Emails',
                EmailReviewStatus = 'EmailReviewStatus (CH-Tbl-Received Emails)'.Error)),
        varRespuestasPendientes: CountRows(
            Filter('CH-Tbl-Received Emails',
                EmailReplyStatus = 'EmailReplyStatus (CH-Tbl-Received Emails)'.Pendiente And ReplyAttempts >= 3))
    }
);
UpdateContext(
    {
        varMinutosSinLatido: If(IsBlank(varLatido), -1,
            DateDiff(varLatido.LastRunOn, Now(), TimeUnit.Minutes))
    }
);
Notify("Estado actualizado.", NotificationType.Success);

UpdateContext(
    {
        varFiltrosQueryCorreo: Concatenate(
            "$filter=",
            If(
                !IsBlank('dp FechaDesde'.SelectedDate),
                "receivedDateTime ge " & Text(
                    'dp FechaDesde'.SelectedDate,
                    "yyyy-mm-dd"
                ) & "T00:00:00Z"
                //,"receivedDateTime ge 2000-01-01T00:00:00Z"
            ),
             If(Or(
                    And(
                        !IsBlank(Trim(SearchInput1_1.Value)),
                        !IsBlank('dp FechaDesde'.SelectedDate)
                    ),And(
                        !IsBlank('dp FechaHasta'.SelectedDate),
                        !IsBlank('dp FechaDesde'.SelectedDate)
                    )
                )," AND "),
            If(
                !IsBlank('dp FechaHasta'.SelectedDate),
                "receivedDateTime le " & Text(
                    'dp FechaHasta'.SelectedDate,
                    "yyyy-mm-dd"
                ) & "T00:00:00Z"
            ),
            If(
                Or(
                    And(
                        !IsBlank(Trim(SearchInput1_1.Value)),
                        !IsBlank('dp FechaHasta'.SelectedDate)
                    )
                ),
                " AND "
            ), 
            If(
                !IsBlank(Trim(SearchInput1_1.Value)),
                //"from/emailAddress/address eq '" & Trim(TextInputCanvas1.Value)&"'"
                "contains(from/emailAddress/address,'" & Trim(SearchInput1_1.Value)&"')"
            )
        )
    }
);

Select(btn_ConstruirURI);
